INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0.029, 122601, 105, 110, 0, "仲間と夏を楽しむ、夏海の魔法士。自分を変えたいという固い決意で、障害物を無効化して走り続ける。", 1.5, 1, 1, 101, 0, 1, 160, 1);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0.014, 122401, 111, 105, 1, "太陽よりも輝く、夏海の元気娘。　持ち前の身体能力で、どんなコースも柔軟に対応し、駆け抜ける。", 2.5, 2, 0, 102, 0, 3, 120, 2);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0.017, 122501, 105, 110, 0, "波打ち際に煌めく、夏海の剣士。　日々の鍛錬で鍛えた脚で、長い距離も速度を落とさず走り切る。", 2.5, 3, 0, 103, 1, 2, 350, 3);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0.016, 107501, 105, 110, 1, "海の幸に目がない、渚のお姫様。　『王家の装備』の力を解放し、障害物をものともせず前へと進む。", 1.5, 4, 0, 104, 0, 3, 130, 4);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0.014, 107601, 105, 110, 0, "海でも主さまをお世話する、白浜の巫女。精霊の力で自身を加速させ、誰よりも速くゴールを目指す。", 2.5, 5, 1, 105, 0, 1, 160, 5);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0.029, 107801, 103, 120, 0, "水着姿を恥じらう、ツンデレ猫娘。お得意の魔法で、対戦相手の走りを妨害し、レースを有利に進める。", 3.5, 6, 0, 106, 1, 2, 255, 6);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0.013, 110601, 103, 120, 0, "優雅に浜を駆ける、真夏のマホ姫。しゃなりしゃなりと、雅な身のこなしで障害物を跳び越えていく。", 3.5, 7, 1, 107, 0, 1, 160, 7);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0.014, 110401, 103, 110, 0, "浜の平和を守る、真夏の狼娘。　　獣人の強靭なスタミナで、レース　後半にスパートをかける。", 2.5, 8, 0, 108, 1, 2, 350, 8);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0.012, 110501, 100, 105, 1, "浜に力強く舞う、真夏の南国娘。　レースの喧噪の中でも精神を乱さず後半に大きな捲りを見せる。", 1.5, 9, 0, 109, 0, 3, 130, 9);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0.014, 115701, 103, 105, 0, "浜の事件を嗅ぎ付けた、真夏の　　名探偵。高い推理力と魔法で、的確に対戦相手の走りを乱す。", 2.5, 10, 1, 110, 0, 1, 200, 10);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0.071, 113601, 103, 105, 0, "再び鎧を脱いだ、灼熱の騎士団長。実戦で培った判断力で、瞬時にバリアを展開し、障害物を無力化する。", 2.5, 11, 0, 111, 1, 2, 350, 11);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0.014, 107901, 103, 120, 1, "水が苦手な、海辺の気まぐれ猫娘。浜に現れた美少女義賊は、対戦相手のスピードを奪いとる。", 1.5, 12, 0, 112, 0, 3, 130, 12);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0.022, 108001, 105, 110, 0, "バカンスも効率第一な、海の傭兵。レースでも最高効率を求め、どんな状況でも隙のない走りを見せる。", 1.5, 13, 1, 113, 0, 2, 200, 13);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0.031, 110301, 108, 110, 0, "真夏の太陽が良く似合う、海辺の　サレンママ。多才で器用、どんな　障害物もエレガントに越えていく。", 2.5, 14, 1, 114, 0, 1, 160, 14);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0.036, 107701, 105, 110, 1, "海に嵐を呼ぶ夏のドジっ娘メイド。日頃から災難に慣れており、多少　のトラブルには動じたりしない。", 0.5, 15, 0, 115, 0, 1, 130, 15);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0.048, 113101, 95, 110, 0, "粋な夏を愉しむ、若夏の姉御。　　流麗な身体捌きで、始・継・終と、UBを重ねるごとに、加速する。", 3.5, 16, 0, 116, 1, 2, 350, 16);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0.043, 113301, 105, 105, 1, "夏のトキメキに触れた、オタク魔法少女。多彩な魔法を操り、少しずつ他の走者の速度を落とし続ける。", 1.5, 17, 0, 117, 0, 3, 130, 17);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0.018, 113201, 95, 105, 1, "海獄に降臨せし、真夏の冥姫。　　レース後半に魔力を全解放し、　　蒼き疾風と成りて浜を駆け抜ける。", 1.5, 18, 0, 118, 0, 2, 130, 18);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0.021, 117001, 108, 110, 0, "夏の夕を火花で彩る、渚の壊し屋。『壊し屋』の異名と過激な愛情は、対戦相手にプレッシャーを与える。", 2.5, 19, 1, 119, 0, 2, 160, 19);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0.036, 113501, 105, 110, 0, "青春に生きる者を導く、夏の先生。夢へと邁進する聖母の加護が、その身をあらゆる困難から守る。", 2.5, 20, 0, 120, 1, 1, 255, 20);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0.02, 113401, 105, 105, 0, "笑顔の応援が眩しい、夏の超能力　ガール。超能力を駆使して、どんな障害物もひとっ飛びで乗り越える。", 2.5, 21, 0, 121, 1, 3, 350, 21);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0.018, 110101, 105, 110, 1, "海辺で大人の魅力を放つ、夏の　　セクシー先生。その魅力に囚われた対戦相手は、走りを乱してしまう。", 2.5, 22, 0, 122, 0, 1, 130, 22);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0.03, 110001, 111, 105, 0, "水着も絶対外さない、夏のカリスマモデル。走りのバイブスは超テンアゲで、スピードはおにやば。", 3.5, 23, 1, 123, 0, 3, 160, 23);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0.027, 117201, 103, 110, 1, "南の島も盛り上げる、真夏のアイドル。悪天候でも笑顔を絶やさず後半もリズムを上げて走り切る。", 1.5, 24, 0, 124, 0, 1, 130, 24);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0.02, 117301, 108, 105, 0, "海原に美声を響かす、渚の歌姫。　守護の賛歌と精霊の加護により、　障害物から身を守る。", 3.5, 25, 1, 125, 0, 2, 160, 25);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0.04, 117401, 105, 110, 0, "夏でも天邪鬼な、夕凪のテーラー。張り巡らされた魔法の糸で、他の走者の自由を奪う。", 2.5, 26, 0, 126, 1, 3, 350, 26);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0.009, 117101, 105, 110, 0, "向日葵が良く似合う、海辺の　　　お姉ちゃん。秘密結社の一員で、　抜群の身体能力が一番の武器。", 3.5, 27, 0, 127, 1, 1, 350, 27);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0.022, 122901, 105, 120, 0, "渚でおっとり、夏色うさぎっこ。　うさぎさんパワー全開で、ぴょん　ぴょんとコースを跳ね回る。", 3.5, 28, 0, 128, 1, 1, 255, 28);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0.028, 122801, 105, 110, 1, "無邪気さ弾ける、夏色いたずら娘。砂浜でも、いたずらの準備は万端！レースに大波乱が巻き起こる！？", 2.5, 29, 0, 129, 0, 3, 130, 29);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (0.023, 122701, 108, 105, 0, "海でも真面目な、夏色優等生。　　高めた魔力を解き放ち、一瞬の内に他の走者を置き去りにする。", 3.5, 30, 1, 130, 0, 2, 130, 30);
